def memberships_to_employees(apps, schema_editor):
    """Каждая прежняя привязка — сотрудник с должностью ADMIN.

    Отозванные привязки (is_active=False) раньше означали «доступа больше
    нет» — теперь это удалённые сотрудники: история остаётся, войти нельзя.
    """
    from django.utils import timezone

    Membership = apps.get_model('organizations', 'OrganizationAdmin')
    now = timezone.now()
    for membership in Membership.objects.select_related('user'):
        user = membership.user
        membership.full_name = ' '.join(p for p in [user.first_name, user.last_name] if p).strip()
        membership.position = 'ADMIN'
        if not membership.is_active:
            membership.deleted_at = membership.deactivated_at or now
        membership.save(update_fields=['full_name', 'position', 'deleted_at'])


